"""
Problem Statement:
-) Santa want to deliver gifts to a huge apartment and he unable to find the right floor based on the instructions provided.
-) He dissects the provided pattern character by character
-) Go through the individual character and conclude a floor number
"""


# First part of the problem
def santa_stair_case_pattern(pattern):
    floor = 0
    for char in pattern:
        if char in "(":
            floor = floor + 1
        elif char in ")":
            floor = floor - 1
    return floor


