def second_half_santa(pattern):
    floor = 0
    basement_position = 0
    for idx, char in enumerate(pattern):
        if char in "(":
            floor = floor + 1
        elif char in ")":
            floor = floor - 1

            if floor <= -1:
                basement_position = idx + 1
                break
    return basement_position


